-- Generated by platform/tools/convert.py: references to the public schema were
-- rewritten to `lms`; private schemas renamed app_private -> lms_private.
-- Edit the source app's migration history only until the cutover; after that, edit here.

SET search_path TO lms, extensions;

-- New local Supabase installations may omit default DML grants for service_role.
-- Server actions already authorize before using it; RLS bypass alone does not
-- confer SQL privileges. Explicitly grant only the application's data tables.
BEGIN;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE
  lms.users, lms.learner_profiles, lms.teacher_assignments,
  lms.modules, lms.module_versions, lms.learner_progress,
  lms.activity_logs, lms.whatsapp_logs, lms.events,
  lms.event_attendances, lms.categories
TO service_role;
-- lms_private.authorization_state remains inaccessible even to service_role.
COMMIT;
